mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM user_posts
    WHERE id = #{postId}
      AND deleted = 0
)

mapper.insert:
INSERT INTO post_comments (
    content, post_id, user_id, created_at, updated_at, deleted
) VALUES (
    #{content}, #{postId}, #{userId}, NOW(), NOW(), 0
)

mapper.update:
UPDATE post_comments
SET content = #{content},
    updated_at = NOW()
WHERE id = #{commentId}
  AND user_id = #{userId}
  AND deleted = 0

UPDATE post_comments
SET deleted = 1,
    deleted_at = NOW()
WHERE id = #{commentId}
  AND user_id = #{userId}
  AND deleted = 0
